import http from "node:http"; import { createReadStream } from "node:fs"; import { mkdir, readFile, writeFile, cp, readdir } from "node:fs/promises"; import path from "node:path"; import { compileWorkbook } from "../packages/compiler/compiler.js"; import { publishManifest, rollback, listVersions } from "../packages/compiler/publisher.js"; import { recordEvent } from "./event-receiver.js"; import { ShareLedger } from "./share-ledger.js";
export interface ServerOptions{host:string;port:number;dataDir:string;rootDir:string;workbook:string;}
const type=(p:string)=>p.endsWith(".js")?"text/javascript":p.endsWith(".json")?"application/json":p.endsWith(".xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"text/html"; const safe=(s:string)=>{if(!/^[a-zA-Z0-9._-]+$/.test(s)) throw new Error("invalid site id"); return s;};
export function createAdRunnerServer(o:ServerOptions){const ledger=new ShareLedger(o.dataDir); return http.createServer(async(req:any,res:any)=>{try{const u=new URL(req.url??"/",`http://${req.headers.host}`); res.setHeader("access-control-allow-origin",String(req.headers.origin??"*")); res.setHeader("access-control-allow-methods","GET,POST,OPTIONS"); if(req.method==="OPTIONS"){res.writeHead(204).end();return;} if(u.pathname==="/v1/ad-runner.min.js") return stream(res,path.join(o.rootDir,"dist/browser/ad-runner.min.js")); if(u.pathname==="/admin") return send(res,adminHtml(o),"text/html"); if(u.pathname==="/admin/workbook.xlsx") return stream(res,o.workbook); if(u.pathname==="/admin/template.xlsx") return stream(res,path.join(o.rootDir,"examples/ad-runner-template.xlsx")); if(u.pathname==="/demo") return send(res,demoHtml(o),"text/html"); if(u.pathname==="/admin/status") return json(res,await status(o)); const m=u.pathname.match(/^\/v1\/sites\/([^/]+)\/(bootstrap|health)\.json$/); if(m) return stream(res,path.join(o.dataDir,"sites",safe(decodeURIComponent(m[1])),`${m[2]}.json`)); const mf=u.pathname.match(/^\/v1\/sites\/([^/]+)\/manifests\/([^/]+)\.json$/); if(mf) return stream(res,path.join(o.dataDir,"sites",safe(decodeURIComponent(mf[1])),"manifests",`${safe(mf[2])}.json`)); const sel=u.pathname.match(/^\/v1\/sites\/([^/]+)\/slots\/([^/]+)\/select$/); if(sel&&req.method==="POST"){const site=decodeURIComponent(sel[1]), slot=decodeURIComponent(sel[2]); const manifest=await currentManifest(o,site); const placement=manifest.placements.find((p:any)=>p.id===slot||p.anchor===slot); if(!placement) throw new Error("slot not found"); return json(res,ledger.select(site,placement,manifest.settings?.debug));} const out=u.pathname.match(/^\/v1\/sites\/([^/]+)\/slots\/([^/]+)\/outcome$/); if(out&&req.method==="POST"){const body=JSON.parse(await readBody(req,8192)||"{}"); return json(res,ledger.outcome(decodeURIComponent(out[1]),decodeURIComponent(out[2]),body));} const led=u.pathname.match(/^\/admin\/sites\/([^/]+)\/ledger$/); if(led) return json(res,{ledger:ledger.rows(decodeURIComponent(led[1]),u.searchParams.get("slot")||"right_rail"),cycles:ledger.cycles(decodeURIComponent(led[1]))}); if(u.pathname==="/admin/ledger/reset"&&req.method==="POST"){ledger.exec("DELETE FROM opportunity_cycles; DELETE FROM partner_slot_ledger;"); return json(res,{ok:true});} const ev=u.pathname.match(/^\/v1\/sites\/([^/]+)\/events$/); if(ev&&req.method==="POST"){const body=await readBody(req,8192); await recordEvent(o.dataDir,decodeURIComponent(ev[1]),JSON.parse(body||"{}")); return json(res,{ok:true});} if(u.pathname==="/admin/workbooks/import"&&req.method==="POST"){await mkdir(path.dirname(o.workbook),{recursive:true}); const body=await readBody(req,20_000_000); await writeFile(o.workbook,Buffer.from(body,"binary"),"binary"); return json(res,await compileWorkbook(o.workbook));} const val=u.pathname.match(/^\/admin\/sites\/([^/]+)\/validate$/); if(val&&req.method==="POST") return json(res,await compileWorkbook(o.workbook)); const pub=u.pathname.match(/^\/admin\/sites\/([^/]+)\/publish$/); if(pub&&req.method==="POST"){const result=await compileWorkbook(o.workbook); const site=result.sites.find(s=>s.site===decodeURIComponent(pub[1])||s.sheetName===decodeURIComponent(pub[1])); if(!site?.manifest||site.errors.length) throw new Error(site?.errors.join("\n")||"site not found"); return json(res,await publishManifest(o.dataDir,site.manifest));} const rb=u.pathname.match(/^\/admin\/sites\/([^/]+)\/rollback\/([^/]+)$/); if(rb&&req.method==="POST") return json(res,await rollback(o.dataDir,decodeURIComponent(rb[1]),decodeURIComponent(rb[2]))); res.writeHead(404).end("not found");}catch(e){json(res,{error:String((e as Error).message)},500)}})}
function stream(res:any,p:string){res.setHeader("content-type",type(p));res.setHeader("cache-control",p.includes("manifests")?"public, max-age=31536000, immutable":"no-cache");createReadStream(p).on("error",()=>{res.writeHead(404).end("not found")}).pipe(res)} function send(res:any,s:string,t:string){res.writeHead(200,{"content-type":t});res.end(s)} function json(res:any,o:any,status=200){res.writeHead(status,{"content-type":"application/json"});res.end(JSON.stringify(o,null,2))} async function readBody(req:any,limit:number){const chunks:any[]=[];let n=0; for await(const c of req){n+=(c as any).length;if(n>limit)throw new Error("payload too large");chunks.push(c as any)} return Buffer.concat(chunks).toString("binary");}
async function status(o:ServerOptions){let compiled; try{compiled=await compileWorkbook(o.workbook)}catch(e){compiled={error:String(e)}} return {workbook:o.workbook,compiled,dataDir:o.dataDir};}
function adminHtml(o:ServerOptions){return `<!doctype html><meta charset=utf-8><title>Ad Runner</title><style>body{font-family:sans-serif;margin:2rem}pre,textarea{background:#f6f6f6;padding:1rem;white-space:pre-wrap}.ok{color:green}.err{color:#b00}</style><h1>Ad Runner Control Panel</h1><p><strong>One slot. Many partners. Many networks. One fair route to a filled advertisement.</strong></p><p>Ad Runner uses the Iterative Partner Model to distribute advertisement opportunities among people, accounts, and networks through one understandable routing system.</p><p>Workbook: <code>${o.workbook}</code> <a href=/admin/template.xlsx>Download starter workbook</a></p><button onclick=load()>Refresh/Validate</button> <button onclick=publishAll()>Publish All</button> <button onclick=resetLedger()>Reset Development Ledger</button> <a href=/demo>Open demo</a><div id=app></div><script>async function load(){let s=await fetch('/admin/status').then(r=>r.json());app.innerHTML='<pre>'+esc(JSON.stringify(s,null,2))+'</pre>';window.status=s;}async function publishAll(){for(const site of (status.compiled.sites||[])){if(site.site&&!site.errors.length) alert(JSON.stringify(await fetch('/admin/sites/'+encodeURIComponent(site.site)+'/publish',{method:'POST'}).then(r=>r.json())))}load()}async function resetLedger(){if(confirm('Reset the development Share Ledger?')){alert(JSON.stringify(await fetch('/admin/ledger/reset',{method:'POST'}).then(r=>r.json())));load()}}function esc(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}load()</script><h2>Integration snippet</h2><pre>&lt;script src="http://localhost:${o.port}/v1/ad-runner.min.js" data-ad-runner-site="animeplex.lol" data-ad-runner-base="http://localhost:${o.port}" defer&gt;&lt;/script&gt;</pre><pre>&lt;div data-ad-runner-slot="top"&gt;&lt;/div&gt;\n&lt;div data-ad-runner-slot="right-rail"&gt;&lt;/div&gt;\n&lt;div data-ad-runner-slot="chapter-end"&gt;&lt;/div&gt;\n&lt;div data-ad-runner-slot="mobile-bottom"&gt;&lt;/div&gt;</pre>`}
function demoHtml(o:ServerOptions){return `<!doctype html><meta charset=utf-8><title>Ad Runner Demo</title><h1>Ad Runner Demo</h1><div data-ad-runner-slot=top style="border:1px solid #aaa;min-height:90px;margin:1rem"></div><div data-ad-runner-slot=right-rail style="border:1px solid #aaa;min-height:250px;margin:1rem"></div><div data-ad-runner-slot=chapter-end style="border:1px solid #aaa;min-height:90px;margin:1rem"></div><div data-ad-runner-slot=mobile-bottom style="border:1px solid #aaa;min-height:90px;margin:1rem"></div><h2>Routing activity</h2><pre id=log></pre><script>['candidate-started','candidate-no-fill','candidate-timeout','candidate-error','candidate-filled','fallback-used','slot-filled','slot-collapsed'].forEach(n=>addEventListener('adrunner:'+n,e=>log.textContent+=n+': '+JSON.stringify(e.detail)+'\n'))</script><script src="/v1/ad-runner.min.js" data-ad-runner-site="animeplex.lol" data-ad-runner-base="http://localhost:${o.port}" defer></script>`}
export async function startServer(o:ServerOptions){await mkdir(path.dirname(o.workbook),{recursive:true}); try{await cp(path.join(o.rootDir,"examples/ad-runner-template.xlsx"),o.workbook,{force:false})}catch{} const s=createAdRunnerServer(o); await new Promise<void>(r=>s.listen(o.port,o.host,r)); console.log(`Ad Runner control panel: http://${o.host}:${o.port}/admin`); console.log(`Demo: http://${o.host}:${o.port}/demo`); return s;}

async function currentManifest(o:ServerOptions,site:string){ const boot=JSON.parse(await readFile(path.join(o.dataDir,"sites",safe(site),"bootstrap.json"),"utf8")); return JSON.parse(await readFile(path.join(o.dataDir,"sites",safe(site),"manifests",`${safe(boot.version)}.json`),"utf8")); }
